int obtener_pib(char *nombre) {
  for (int p = 0; p < num_paises; ++p) {
    if (compara_cadena(nombre, paises[p].nombre)) {
      return paises[p].habitantes * paises[p].pib_per_capita;
    }
  }
  return -1;
}
